99: static char *strrspn(const char *s, const char *charset)
100: {
101: 	char *t = (char *)s + strlen(s);
102: 	while (t != (char *)s)
103: 		if (!strchr(charset, *(--t)))
104: 			return ++t;
105: 	return t;
106: }
