108: static int strend(const char *str, const char *pattern)
109: {
110: 	size_t slen = strlen(str);
111: 	size_t plen = strlen(pattern);
112: 	if (slen >= plen)
113: 		return (!memcmp(pattern, (str + slen - plen), plen));
114: 	return 0;
115: }
