793: 			if (errno == EINTR) {
794: 				DEBUG("tcdrain() was interrupted");
795: 				continue;
796: 			} else {
797: 				RETURN_FAIL("tcdrain() failed");
798: 			}
799: 		} else {
800: 			RETURN_OK();
801: 		}
802: 	}
803: #endif
