1320: 	}
1321: 
1322: 	/* Do read. */
1323: 	if (ReadFile(port->hdl, buf, (DWORD) count, NULL, &port->read_ovl) == 0)
1324: 		if (GetLastError() != ERROR_IO_PENDING)
1325: 			RETURN_FAIL("ReadFile() failed");
1326: 
